import { IconEye, IconEyeOff, IconTrashCan } from '@hawkins/assets';
import { Button } from '@hawkins/components';
import { formatKey } from '@ncgt/common/utils/envVar';
import { InputField } from '../InputField';
import styles from './EnvVarRow.module.css';

export interface EnvVarRowProps {
    index: number;
    /** Whether this env var is enabled (sent to the game). */
    isEnabled: boolean;
    /** Whether a game session is currently active. Disables row edits while playing. */
    isPlaying?: boolean;
    onToggleEnabled: () => void;
    onRemove: () => void;
}

export const EnvVarRow = ({
    index,
    isEnabled,
    isPlaying,
    onToggleEnabled,
    onRemove,
}: EnvVarRowProps) => {
    const inputsDisabled = isPlaying || !isEnabled;
    const toggleLabel = 'Disable/enable the variable';
    return (
        <tr>
            <td>
                <InputField
                    name={`vars.${index}.key`}
                    disabled={inputsDisabled}
                    autoEndAdornment={false}
                    transformValue={formatKey}
                />
            </td>
            <td>
                <InputField
                    name={`vars.${index}.value`}
                    disabled={inputsDisabled}
                    autoEndAdornment={false}
                />
            </td>
            <td className={styles.actionCell}>
                <Button
                    compact
                    className={styles.toggleButton}
                    variant='icon'
                    icon={isEnabled ? IconEye : IconEyeOff}
                    disabled={isPlaying}
                    aria-label={toggleLabel}
                    tooltipLabel={toggleLabel}
                    tooltipProps={{ disabled: isPlaying }}
                    onClick={onToggleEnabled}
                />
                <Button
                    compact
                    variant='icon'
                    icon={IconTrashCan}
                    disabled={isPlaying}
                    aria-label='Remove Variable'
                    tooltipLabel='Remove Variable'
                    tooltipProps={{ disabled: isPlaying }}
                    onClick={onRemove}
                />
            </td>
        </tr>
    );
};
