import { Button, Divider, Text } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import type { ReactNode } from 'react';
import { EnvVarRow } from '../EnvVarRow';
import styles from './EnvVarTable.module.css';

export interface EnvVarTableField {
    id: string;
    enabled?: boolean;
}

export interface EnvVarTableProps {
    fields: EnvVarTableField[];
    description?: ReactNode;
    disabled?: boolean;
    onAdd: () => void;
    onRemove: (index: number) => void;
    onToggleEnabled: (index: number, isEnabled: boolean) => void;
}

export const EnvVarTable = ({ fields, description, disabled, onAdd, onRemove, onToggleEnabled }: EnvVarTableProps) => {
    return (
        <div className={styles.container}>
            {description && (
                <Text variant='body' colorVariant='faded'>
                    {description}
                </Text>
            )}
            <table className={styles.table}>
                <thead>
                    <tr>
                        <th className={styles.headerCell}>
                            <Text colorVariant='faded' bold>
                                Key
                            </Text>
                        </th>
                        <th className={styles.headerCell}>
                            <Text colorVariant='faded' bold>
                                Value
                            </Text>
                        </th>
                        <th />
                    </tr>
                </thead>
                <tbody>
                    {fields.map((field, index) => {
                        const isEnabled = field.enabled !== false;
                        return (
                            <EnvVarRow
                                key={field.id}
                                index={index}
                                isEnabled={isEnabled}
                                isPlaying={disabled}
                                onToggleEnabled={() => onToggleEnabled(index, isEnabled)}
                                onRemove={() => onRemove(index)}
                            />
                        );
                    })}
                </tbody>
            </table>
            <Divider style={{ margin: `${Dimensions.Space12} 0` }} />
            <div className={styles.actions}>
                <Button onClick={onAdd} variant='secondary' disabled={disabled} className={styles.add}>
                    Add Variable
                </Button>
            </div>
        </div>
    );
};
